function openIndicate(){if(!canPost())return;editor={kind:'indicate',photos:[]};editorDirty=false;showDialog('Indicar um negócio',`<div class="form-grid">${field('ind-name','Nome do negócio','','required minlength="3" class="full"')}${selectField('ind-category','Tipo de serviço',[['','Escolher'],...GROUP_NAMES],'','required')}${hoodField('ind-hood')}${field('ind-why','Por que você indica?','','type="textarea" rows="3" required minlength="12" class="full"')}</div><p class="form-note">A página nasce com a sua indicação. O responsável poderá completar as informações depois.</p>`,`${btn('Cancelar','close-dialog','','text')}${btn('Publicar indicação','submit-indicate','','filled','thumb_up')}`,'editor');}
async function submitIndicate(){if(!canPost()||!validFields(['ind-name','ind-category','ind-hood','ind-why']))return;const name=$('#ind-name').value.trim(),cat=$('#ind-category').value,hood=$('#ind-hood').value,why=$('#ind-why').value.trim();if(!GROUP_NAMES.includes(cat)){notify('Escolha o tipo de serviço do negócio.','error');return;}if(cityHasHoods(state.homeCity)&&!HOODS.includes(hood)){notify('Escolha o bairro da lista.','error');return;}const duplicate=cityBiz().find(b=>norm(b.name)===norm(name));if(duplicate?.myInd){await closeDialog(true);navigate('negocio',duplicate.id);notify('Você já indicou este negócio.','info');return;}const id=duplicate?.id||uid('b');const ok=mutate(()=>{if(duplicate){if(!duplicate.myInd)duplicate.recN++;duplicate.myInd=true;duplicate.says.push([initals(state.profile.name),'me',state.profile.name,why]);}else state.biz.unshift({id,name,city:state.homeCity,cat,hoods:hood?[hood]:[],svc:[],bio:'',hours:'A confirmar com o responsável',photos:[],icon:'storefront',ini:initals(name),claimed:false,myInd:true,recN:1,says:[[initals(state.profile.name),'me',state.profile.name,why]],saved:false});},{redraw:false});if(ok){await closeDialog(true);navigate('negocio',id);notify(duplicate?'Sua indicação foi adicionada':'Negócio indicado');}}
